class PreviewAuth extends ChangeNotifier implements AuthProvider {
 @override User? get dbUser=>const User(id:'diary-fixture',username:'Diary demo',email:'',iconColorId:0,completedSetup:true,darkMode:true);
 @override int get activityVersion=>0;
 @override dynamic noSuchMethod(Invocation invocation)=>null;
}
class PreviewData extends ProfileDataService {
 @override Future<List<MovieWatchEntry>> movieWatches(String userId)async=>[
  for(final spec in [('a',348,'Alien','2026-10-12T18:00:00Z',true,'alien',9),('b',557,'Spider-Man','2026-10-14T18:00:00Z',false,'spider',8),('c',157336,'Interstellar','2026-10-16T18:00:00Z',false,'interstellar',10)])
   MovieWatchEntry.fromJson({'id':spec.$1,'userId':userId,'movieId':spec.$2,'watchedAt':spec.$4,'watchedAtCinema':spec.$5,'rating':spec.$7,'notes':spec.$1=='a'?'Still makes me jump.':spec.$1=='b'?'A comfort watch.':'That ending. Every time.','movie':{'id':spec.$2,'title':spec.$3,'posterPath':'https://image.tmdb.org/t/p/w185/${spec.$6}-demo.jpg'},'companions':spec.$1=='b'?[]:[{'id':'sophie','username':'Sophie','profileBadges':['EARLY_ADOPTER']},if(spec.$1=='c'){'id':'robin','username':'Robin','profileBadges':['FOUNDER']}]}),
 ];
}
Future<void> main()async{
 WidgetsFlutterBinding.ensureInitialized();
 await DefaultCacheManager().putFile('https://image.tmdb.org/t/p/w185/alien-demo.jpg',base64Decode(''),fileExtension:'jpg',maxAge:const Duration(days:1));
 await DefaultCacheManager().putFile('https://image.tmdb.org/t/p/w185/interstellar-demo.jpg',base64Decode(''),fileExtension:'jpg',maxAge:const Duration(days:1));
 await DefaultCacheManager().putFile('https://image.tmdb.org/t/p/w185/spider-demo.jpg',base64Decode(''),fileExtension:'jpg',maxAge:const Duration(days:1));
 runApp(MaterialApp(debugShowCheckedModeBanner:false,theme:AppTheme.darkTheme,builder:(context,child)=>Banner(message:'DEMO',location:BannerLocation.topEnd,color:const Color(0xff67547d),child:child!),home:const PreviewHome()));
}
class PreviewHome extends StatefulWidget {const PreviewHome({super.key});@override State<PreviewHome> createState()=>_PreviewHomeState();}
class _PreviewHomeState extends State<PreviewHome> {
 @override void initState(){super.initState();WidgetsBinding.instance.addPostFrameCallback((_){Navigator.of(context).push(MaterialPageRoute<void>(builder:(_)=>ProfileDiaryScreen(controller:ProfileDiaryController(auth:PreviewAuth(),service:PreviewData()),today:DateTime(2026,10,17))));});}
 @override Widget build(BuildContext context)=>const Scaffold(body:Center(child:Text('Fictional diary preview')));
}
